import { useContext, useState } from "react";
import { AuthContext } from "../../context/authContext";
import { Link } from "react-router-dom";
import Friends from "../../assets/1.png";
import Groups from "../../assets/2.png";
import Gallery from "../../assets/8.png";
import Videos from "../../assets/9.png";
import Messages from "../../assets/10.png";
import Addfrnds from "../../assets/add_frnds.png";
import "./leftBar.scss";

const LeftBar = () => {
  const { currentUser } = useContext(AuthContext);
  const [showFriends, setShowFriends] = useState(false);

  // Mock friends data (replace with API if available)
  const friends = [
    {
      id: 1,
      name: "John Doe",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
    {
      id: 2,
      name: "Jane Doe",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
    {
      id: 3,
      name: "Sam Smith",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
  ];

  const handleFriendsClick = () => {
    setShowFriends(!showFriends);
  };

  return (
    <div className="leftBar">
      <div className="container">
        <div className="menu">
          <div className="user">
            <Link to={`/profile/${currentUser?.id}`} style={{ textDecoration: 'none' }}>
              <img src={currentUser?.profilePic} alt={`${currentUser?.name}'s profile`} />
              <span>{currentUser?.name}</span>
            </Link>
          </div>
          <Link
            to="/friends"
            className="item"
            style={{ textDecoration: 'none' }}
            onClick={handleFriendsClick}
          >
            <img src={Friends} alt="Friends icon" />
            <span>Friends</span>
          </Link>
          {showFriends && (
            <div className="friends-list">
              <h3>Your Friends</h3>
              {friends.length > 0 ? (
                friends.map((friend) => (
                  <div className="friend" key={friend.id}>
                    <img src={friend.profilePic} alt={`${friend.name}'s profile`} />
                    <span>{friend.name}</span>
                  </div>
                ))
              ) : (
                <p>No friends found.</p>
              )}
            </div>
          )}
          <Link to="/groups" className="item" style={{ textDecoration: 'none' }}>
            <img src={Groups} alt="Groups icon" />
            <span>Groups</span>
          </Link>
        </div>
        <hr />
        <div className="menu">
          <span>Your shortcuts</span>
          <Link to="/add-friends" className="item" style={{ textDecoration: 'none' }}>
            <img src={Addfrnds} alt="Add Friends icon" />
            <span>Add Friends</span>
          </Link>
          <Link to="/photos" className="item" style={{ textDecoration: 'none' }}>
            <img src={Gallery} alt="Photos icon" />
            <span>Photos</span>
          </Link>
          <Link to="/videos" className="item" style={{ textDecoration: 'none' }}>
            <img src={Videos} alt="Videos icon" />
            <span>Videos</span>
          </Link>
          <Link to="/messages" className="item" style={{ textDecoration: 'none' }}>
            <img src={Messages} alt="Messages icon" />
            <span>Messages</span>
          </Link>
        </div>
        <hr />
      </div>
    </div>
  );
};

export default LeftBar;
